// ScoreResponse is the unified shape returned by both score RPCs.
type ScoreResponse struct {
	Confidence   float64
	Verdict      string
	TopFeatures  []*FeatureWeight
	LatencyMs    float64
	ModelVersion string
	InputHash    string
}

func (m *ScoreResponse) Reset() { *m = ScoreResponse{} }
func (m *ScoreResponse) String() string {
	return fmt.Sprintf("ScoreResponse{verdict=%q, conf=%.3f, model=%q}",
		m.Verdict, m.Confidence, m.ModelVersion)
}
func (*ScoreResponse) ProtoMessage() {}

func (m *ScoreResponse) MarshalVT() ([]byte, error) {
	var b []byte
	b = appendDouble(b, 1, m.Confidence)
	b = appendString(b, 2, m.Verdict)
	for _, f := range m.TopFeatures {
		fb, err := f.MarshalVT()
		if err != nil {
			return nil, err
		}
		b = appendBytes(b, 3, fb)
	}
	b = appendDouble(b, 4, m.LatencyMs)
	b = appendString(b, 5, m.ModelVersion)
	b = appendString(b, 6, m.InputHash)
	return b, nil
}

func (m *ScoreResponse) UnmarshalVT(data []byte) error {
	for len(data) > 0 {
		num, typ, n := protowire.ConsumeTag(data)
		if err := protowire.ParseError(n); err != nil {
			return err
		}
		data = data[n:]
		switch num {
		case 1:
			f, n := consumeDouble(data, typ)
			m.Confidence = f
			data = data[n:]
		case 2:
			s, n := consumeString(data, typ)
			m.Verdict = s
			data = data[n:]
		case 3:
			raw, n := consumeMessage(data, typ)
			fw := &FeatureWeight{}
			if err := fw.UnmarshalVT(raw); err != nil {
				return err
			}
			m.TopFeatures = append(m.TopFeatures, fw)
			data = data[n:]
		case 4:
			f, n := consumeDouble(data, typ)
			m.LatencyMs = f
			data = data[n:]
		case 5:
			s, n := consumeString(data, typ)
			m.ModelVersion = s
			data = data[n:]
		case 6:
			s, n := consumeString(data, typ)
			m.InputHash = s
			data = data[n:]
		default:
			n := protowire.ConsumeFieldValue(num, typ, data)
			if err := protowire.ParseError(n); err != nil {
				return err
			}
			data = data[n:]
		}
	}
	return nil
}

