// ─── wire-format helpers ────────────────────────────────────────────

func appendString(b []byte, num protowire.Number, s string) []byte {
	if s == "" {
		return b
	}
	b = protowire.AppendTag(b, num, protowire.BytesType)
	b = protowire.AppendString(b, s)
	return b
}

func appendBytes(b []byte, num protowire.Number, v []byte) []byte {
	b = protowire.AppendTag(b, num, protowire.BytesType)
	b = protowire.AppendBytes(b, v)
	return b
}

func appendDouble(b []byte, num protowire.Number, f float64) []byte {
	if f == 0 {
		return b
	}
	b = protowire.AppendTag(b, num, protowire.Fixed64Type)
	b = protowire.AppendFixed64(b, math_Float64bits(f))
	return b
}

func appendVarint(b []byte, num protowire.Number, v uint64) []byte {
	if v == 0 {
		return b
	}
	b = protowire.AppendTag(b, num, protowire.VarintType)
	b = protowire.AppendVarint(b, v)
	return b
}

func consumeString(data []byte, typ protowire.Type) (string, int) {
	if typ != protowire.BytesType {
		n := protowire.ConsumeFieldValue(0, typ, data)
		return "", n
	}
	v, n := protowire.ConsumeString(data)
	return v, n
}

func consumeMessage(data []byte, typ protowire.Type) ([]byte, int) {
	if typ != protowire.BytesType {
		n := protowire.ConsumeFieldValue(0, typ, data)
		return nil, n
	}
	v, n := protowire.ConsumeBytes(data)
	return v, n
}

func consumeBytes(data []byte, typ protowire.Type) ([]byte, int) {
	if typ != protowire.BytesType {
		n := protowire.ConsumeFieldValue(0, typ, data)
		return nil, n
	}
	v, n := protowire.ConsumeBytes(data)
	// Return a copy so the caller owns the slice independently of the
	// input buffer — matches proto3 semantics for bytes fields.
	out := make([]byte, len(v))
	copy(out, v)
	return out, n
}

func consumeDouble(data []byte, typ protowire.Type) (float64, int) {
	if typ != protowire.Fixed64Type {
		n := protowire.ConsumeFieldValue(0, typ, data)
		return 0, n
	}
	v, n := protowire.ConsumeFixed64(data)
	return math_Float64frombits(v), n
}

func consumeVarint(data []byte, typ protowire.Type) (uint64, int) {
	if typ != protowire.VarintType {
		n := protowire.ConsumeFieldValue(0, typ, data)
		return 0, n
	}
	v, n := protowire.ConsumeVarint(data)
	return v, n
}

func appendFloat32(b []byte, num protowire.Number, f float32) []byte {
	if f == 0 {
		return b
	}
	b = protowire.AppendTag(b, num, protowire.Fixed32Type)
	b = protowire.AppendFixed32(b, math_Float32bits(f))
	return b
}

func consumeFloat32(data []byte, typ protowire.Type) (float32, int) {
	if typ != protowire.Fixed32Type {
		n := protowire.ConsumeFieldValue(0, typ, data)
		return 0, n
	}
	v, n := protowire.ConsumeFixed32(data)
	return math_Float32frombits(v), n
}
